/**
 * The Player page (spec uiux/specs/2026-10-25-video-player.md §24.3, mock-up
 * 32-app-watch; named Player since 27 Oct 2026, uiux 2026-10-27-player-tab):
 * the learning window's way to the dark Player window and back. "Open the
 * Player" (⌘2 / Ctrl+2), a drop card and "Open a video…" (⌘O / Ctrl+O) open
 * the Player (nothing plays in this
 * window; a video dropped anywhere on it opens the Player too), Continue
 * watching is the Player's own list, and "Words from your videos" groups
 * the words saved there by video, each group with "Practise these".
 * Desktop app only.
 */
import { useEffect, useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import type { Word } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { listNotebooks, listWords } from '@/db/repo.js';
import { plural, t } from '@/i18n/index.js';
import { isoDayLabel } from '@/lib/format.js';
import { platform } from '@/lib/platform/index.js';
import type { RecentEntry } from '@/lib/platform/media.js';
import type { PlayerHost } from '@/lib/platform/types.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { episodeCode, parseTitle } from '@/features/player/model/title.js';
import { minutesLeft } from '@/features/player/model/time.js';
import { groupVideoWords, type VideoGroup } from './videoWords.js';
import styles from './Watch.module.css';

/** The most cards Continue watching shows here (§24.3). */
const MAX_RECENT = 6;
/** Word chips per video before "+n". */
const MAX_CHIPS = 4;

async function allWords(): Promise<Word[]> {
  const notebooks = await listNotebooks();
  const lists = await Promise.all(notebooks.map((n) => listWords(n.id)));
  return lists.flat();
}

export function Watch(): React.JSX.Element {
  const player = platform.desktop?.player;
  if (player === undefined) {
    return (
      <main className={styles.screen}>
        <p className={styles.only}>{t('player.unavailable.title')}</p>
      </main>
    );
  }
  return <WatchPage player={player} />;
}

function WatchPage({ player }: { player: PlayerHost }): React.JSX.Element {
  const navigate = useNavigate();
  const [recent, setRecent] = useState<RecentEntry[] | null>(null);
  const [failed, setFailed] = useState(false);
  const words = useLiveQuery(allWords, [] as Word[], []);
  const groups = groupVideoWords(words);
  const mac = player.window.os === 'macos';
  // The keys as each system writes them (⌘2 on a Mac, Ctrl+2 on Windows).
  const keycap = (key: string): string => (mac ? `⌘${key}` : `Ctrl+${key}`);
  const shortcut = (key: string): string => `${mac ? 'Meta' : 'Control'}+${key}`;

  useEffect(() => {
    let live = true;
    const read = (): void => {
      void player.media
        .recent()
        .then((r) => {
          if (live) setRecent(r);
        })
        .catch(() => {
          if (live) setRecent([]);
        });
    };
    read();
    window.addEventListener('focus', read);
    return () => {
      live = false;
      window.removeEventListener('focus', read);
    };
  }, [player]);

  const open = (opts: { pick?: boolean; fileId?: string } = {}): void => {
    setFailed(false);
    player.openPlayer(opts).catch(() => {
      setFailed(true);
    });
  };

  const cards = (recent ?? []).slice(0, MAX_RECENT);
  const today = new Date().toISOString().slice(0, 10);

  return (
    <main className={styles.screen}>
      <header className={styles.head}>
        <div>
          <p className={styles.eyebrow}>{t('watch.eyebrow')}</p>
          <h1 className={styles.title}>{t('watch.title')}</h1>
        </div>
        <button
          type="button"
          className={styles.playerButton}
          aria-keyshortcuts={shortcut('2')}
          onClick={() => {
            open();
          }}
        >
          <Icon name="watch" size={18} />
          {t('watch.playerKey')}
          <kbd className={styles.kbd} dir="ltr" aria-hidden="true">
            {keycap('2')}
          </kbd>
        </button>
      </header>

      <section className={styles.drop}>
        <span className={styles.dropTile}>
          <Icon name="film" size={26} />
        </span>
        <div className={styles.dropText}>
          <h2 className={styles.dropTitle}>{t('watch.drop')}</h2>
          <p className={styles.dropFormats}>{t('watch.formats')}</p>
        </div>
        <button
          type="button"
          className={styles.open}
          aria-keyshortcuts={shortcut('O')}
          onClick={() => {
            open({ pick: true });
          }}
        >
          <Icon name="folder" size={18} />
          {t('watch.open')}
          <kbd className={styles.openKbd} dir="ltr" aria-hidden="true">
            {keycap('O')}
          </kbd>
        </button>
      </section>
      {failed ? (
        <p className={styles.failed} role="status">
          {t('watch.openFailed')}
        </p>
      ) : null}

      {cards.length > 0 ? (
        <section className={styles.section} aria-labelledby="watch-recent">
          <div className={styles.sectionHead}>
            <h2 id="watch-recent" className={styles.sectionTitle}>
              {t('watch.recent')}
            </h2>
          </div>
          <ul className={styles.cards}>
            {cards.map((r) => (
              <RecentCard
                key={r.key}
                entry={r}
                onOpen={() => {
                  if (r.fileId !== undefined) open({ fileId: r.fileId });
                  else open();
                }}
              />
            ))}
          </ul>
        </section>
      ) : null}

      {groups.length > 0 ? (
        <section className={styles.section} aria-labelledby="watch-words">
          <div className={styles.sectionHead}>
            <h2 id="watch-words" className={styles.sectionTitle}>
              {t('watch.words')}
            </h2>
            <Link to="/notebook" className={styles.link}>
              {t('watch.seeAll')}
            </Link>
          </div>
          <ul className={styles.groups}>
            {groups.map((g) => (
              <GroupRow
                key={g.title}
                group={g}
                thumb={cards.find((c) => parseTitle(c.name).title === g.show)?.thumb}
                when={isoDayLabel(g.latest.slice(0, 10), today)}
                onPractise={() => {
                  void navigate(`/session?deck=group&ids=${g.words.map((w) => w.id).join(',')}`);
                }}
              />
            ))}
          </ul>
        </section>
      ) : null}
    </main>
  );
}

function RecentCard({ entry, onOpen }: { entry: RecentEntry; onOpen: () => void }): React.JSX.Element {
  const title = parseTitle(entry.name);
  const code = episodeCode({
    ...title,
    ...(entry.season !== undefined ? { season: entry.season } : {}),
    ...(entry.episode !== undefined ? { episode: entry.episode } : {}),
  });
  const name = code === undefined ? title.title : `${title.title} · ${code}`;
  const pct = entry.duration > 0 ? Math.min(100, (entry.position / entry.duration) * 100) : 0;
  return (
    <li className={styles.card}>
      <button type="button" className={styles.cardButton} onClick={onOpen} disabled={entry.missing}>
        <span className={styles.thumb}>
          {entry.thumb !== undefined ? (
            <img src={entry.thumb} alt="" className={styles.thumbImg} draggable={false} />
          ) : (
            <Icon name="film" size={26} className={styles.thumbIcon} />
          )}
          <span className={styles.bar} dir="ltr">
            <span className={styles.fill} style={{ width: `${String(entry.watched ? 100 : pct)}%` }} />
          </span>
        </span>
        <span className={styles.cardTitle}>{name}</span>
        <span className={styles.cardMeta}>
          {entry.missing
            ? t('player.recent.moved')
            : entry.watched
              ? t('player.recent.finished')
              : t('player.recent.minLeft', { count: minutesLeft(entry.position, entry.duration) })}
        </span>
      </button>
    </li>
  );
}

function GroupRow({
  group,
  thumb,
  when,
  onPractise,
}: {
  group: VideoGroup;
  thumb: string | undefined;
  when: string;
  onPractise: () => void;
}): React.JSX.Element {
  const n = group.words.length;
  const chips = group.words.slice(0, MAX_CHIPS);
  return (
    <li className={styles.group}>
      <span className={styles.groupThumb}>
        {thumb !== undefined ? (
          <img src={thumb} alt="" className={styles.thumbImg} draggable={false} />
        ) : (
          <Icon name="film" size={20} className={styles.thumbIcon} />
        )}
      </span>
      <div className={styles.groupText}>
        <div className={styles.groupHead}>
          <b className={styles.groupTitle}>{group.title}</b>
          <span className={styles.groupMeta}>
            {plural(n, 'watch.wordsMetaOne', 'watch.wordsMeta', { count: n, when })}
          </span>
        </div>
        <div className={styles.chips}>
          {chips.map((w) => (
            <Link key={w.id} to={`/words/${w.id}`} className={styles.chip} dir="auto">
              {w.headword}
            </Link>
          ))}
          {n > MAX_CHIPS ? (
            <span className={styles.chipMore}>{t('watch.more', { count: n - MAX_CHIPS })}</span>
          ) : null}
        </div>
      </div>
      <button type="button" className={styles.practise} onClick={onPractise}>
        {plural(n, 'watch.practiseOne', 'watch.practise', { count: n })}
      </button>
    </li>
  );
}
