/**
 * Which notebook words came from the desktop app's video player: their
 * private note is the player's "Seen in" line, "Seen in The Terrace · S1 E3
 * · 26:58" (features/player/model/words.ts `seenIn`), and nothing else
 * writes a note ending in a time. Grouped by video for the Watch page
 * (spec uiux/specs/2026-10-25-video-player.md §24.3). Pure, so it is tested.
 */
import type { Word } from '@lexpad/core';
import { SEEN_IN } from '@/lib/seenIn.js';

export interface VideoGroup {
  /** "The Terrace · S1 E3", or the film's title alone. */
  title: string;
  /** The video's own title, without the episode, to find its frame in Continue watching. */
  show: string;
  words: Word[];
  /** The newest word's time, an ISO string. */
  latest: string;
}

/** "Seen in <title>[ · S1 E3] · <m:ss or h:mm:ss>" */
const NOTE = new RegExp(`^${SEEN_IN}(.+?)(?: · (S\\d+ E\\d+|E\\d+))? · (\\d{1,2}:\\d{2}(?::\\d{2})?)$`, 'u');

export function videoOf(memo: string | undefined): { show: string; episode: string | undefined } | undefined {
  if (memo === undefined) return undefined;
  const m = NOTE.exec(memo.trim());
  if (m === null) return undefined;
  return { show: m[1] ?? '', episode: m[2] };
}

/** The video words, a group per video, the newest video first, each group's words newest first. */
export function groupVideoWords(words: readonly Word[]): VideoGroup[] {
  const groups = new Map<string, VideoGroup>();
  for (const w of words) {
    const v = videoOf(w.progress?.memo);
    if (v === undefined) continue;
    const title = v.episode === undefined ? v.show : `${v.show} · ${v.episode}`;
    const g = groups.get(title) ?? { title, show: v.show, words: [], latest: w.createdAt };
    g.words.push(w);
    if (Date.parse(w.createdAt) > Date.parse(g.latest)) g.latest = w.createdAt;
    groups.set(title, g);
  }
  const list = [...groups.values()];
  for (const g of list) g.words.sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));
  return list.sort((a, b) => Date.parse(b.latest) - Date.parse(a.latest));
}
